14|pub(crate) fn request(operation: &str, actor: &str, session: &str, genesis: &str,
15|    kind: &str, target: &str, body: Value) -> Result<NativeCreationRequest> {
16|    ensure!(body.is_object() && body.get("name").is_none(), "native name is server assigned");
17|    let plugin = match kind { "identity" => "identity_sled", "project" => "project", "incus" => "incus",
18|        _ => anyhow::bail!("unknown native owner") };
19|    let pin = crate::sealed_schema_reader::read_manifest_pinned_schema_document(
20|        &crate::sealed_schema_reader::blob_catalog_dir_from_env(), plugin)?;
21|    let request_json = serde_json::to_string(&body)?;
22|    let request_digest = format!("{:x}", Sha256::digest(request_json.as_bytes()));
23|    Ok(NativeCreationRequest { operation_id: operation.into(), actor_id: actor.into(),
24|        caller_session: session.into(), caller_genesis: genesis.into(), owner_kind: kind.into(),
25|        logical_target: target.into(), schema_hash: pin.schema_hash, request_digest, request_json })
26|}
