48|/// Caller holds lifecycle (if applicable), then host observation lock. The
49|/// durable intent is committed and flushed before the sole POST permission.
50|pub(crate) async fn create_locked(engine: &MutationEngine, request: NativeCreationRequest)
51|    -> Result<(NativeCreationRecord, bool)> {
52|    admit(engine, &request).await?;
53|    let native = IncusRootRepairBackend::local();
54|    let before = native.default_project_state().await?;
55|    if request.owner_kind == "project" {
56|        let prior = records(engine).await?;
57|        ensure!(!before.instances.iter().any(|i|
58|            (i.name == request.logical_target || i.config.as_ref().is_some_and(|c|
59|                c.get("user.opdbus.project_id") == Some(&request.logical_target)))
60|            && !prior.iter().any(|r| r.name == i.name && r.request.operation_id == request.operation_id)),
61|            "existing project native binding must not be recreated");
62|    }
63|    let names = before.instances.iter().map(|i| i.name.clone()).collect::<Vec<_>>();
64|    let cozo = engine.identity_sled_store()?.cozo().clone();
65|    let (record, fresh) = tokio::task::spawn_blocking(move || cozo.reserve_native_creation(request, &names)).await??;
66|    // Any failure from here retains the fence, including definite provider
67|    // errors. An absent object is not proof that an earlier POST was rejected.
68|    if fresh {
69|        admit(engine, &record.request).await?;
70|        let mut body: Value = serde_json::from_str(&record.request.request_json)?;
71|        body["name"] = record.name.clone().into();
72|        body["config"]["user.opdbus.creation_operation"] = record.request.operation_id.clone().into();
73|        body["config"]["user.opdbus.creation_digest"] = record.request.request_digest.clone().into();
74|        incus::create_reserved_native(&body).await
75|            .context("native POST outcome requires reconciliation; reservation retained")?;
76|    }
77|    let record = reconcile_locked(engine, record).await?;
78|    Ok((record, !fresh))
