81|pub(crate) async fn reconcile_locked(engine: &MutationEngine, record: NativeCreationRecord)
82|    -> Result<NativeCreationRecord> {
83|    admit(engine, &record.request).await?;
84|    let native = IncusRootRepairBackend::local();
85|    let (raw, _) = native.instance(&record.name).await
86|        .context("reserved native instance absent or unreadable; POST will not be repeated")?;
87|    let body: Value = serde_json::from_str(&record.request.request_json)?;
88|    ensure!(raw["name"] == record.name && raw["type"] == body["type"]
89|        && raw["config"]["user.opdbus.creation_operation"] == record.request.operation_id
90|        && raw["config"]["user.opdbus.creation_digest"] == record.request.request_digest,
91|        "native creation ownership markers differ");
92|    if record.phase != "complete" {
93|        ensure!(raw["status"] == "Stopped" && raw["status_code"] == 102
94|            && raw["profiles"] == body["profiles"] && raw["devices"] == body["devices"],
95|            "native preparation is not the pinned stopped definition");
96|        if record.request.owner_kind == "identity" {
97|            ensure!(raw["expanded_config"]["security.privileged"] == "false"
98|                && raw["expanded_config"]["security.nesting"] == "false"
99|                && raw["expanded_config"]["boot.autostart"] == "false"
100|                && raw["expanded_config"]["raw.lxc"] == body["config"]["raw.lxc"],
101|                "expanded native identity security differs");
102|            let expanded = raw["expanded_devices"].as_object().context("expanded devices absent")?;
103|            ensure!(expanded.len() == 3 && expanded.get("root") == body["devices"].get("root")
104|                && expanded.get("runtime-run") == body["devices"].get("runtime-run")
105|                && expanded.get("lungs-socket-dir") == Some(&json!({"type":"disk", "source":"/run/opdbus/lungs",
106|                    "path":"/run/opdbus/lungs", "readonly":"true"})), "expanded identity devices differ");
107|        }
108|        for (key, value) in body["config"].as_object().context("creation config missing")? {
109|            ensure!(raw["config"].get(key) == Some(value), "native creation config differs");
110|        }
111|    }
112|    let native_uuid = raw["config"]["volatile.uuid"].as_str().context("native UUID absent")?.to_owned();
113|    ensure!(uuid::Uuid::parse_str(&native_uuid)?.to_string() == native_uuid, "noncanonical native UUID");
114|    let cozo = engine.identity_sled_store()?.cozo().clone();
115|    let pinned = record.clone();
116|    let bound = tokio::task::spawn_blocking(move || cozo.bind_native_creation(&pinned, &native_uuid)).await??;
117|    let snapshot = native.default_project_state().await?;
118|    let instance = snapshot.instances.iter().find(|i| i.name == bound.name)
119|        .context("created instance missing from full readback")?;
120|    ensure!(serde_json::to_value(instance)? == serde_json::to_value(incus::IncusPlugin::instance_from_native_metadata(raw)?)?,
121|        "native instance changed during full readback");
122|    crate::incus_observer::publish_repair_readback_locked(engine, &snapshot).await?;
123|    let cozo = engine.identity_sled_store()?.cozo().clone();
124|    Ok(tokio::task::spawn_blocking(move || cozo.complete_native_creation(&bound)).await??)
125|}
