127|pub(crate) async fn dispatch(engine: &MutationEngine, method: &str, args: &Value,
128|    actor: &str, session: Option<&str>, genesis: Option<&str>) -> Result<Value> {
129|    let session = session.context("native creation requires verified session")?.to_owned();
130|    let genesis = genesis.context("native creation requires verified genesis")?.to_owned();
131|    let engine = engine.clone();
132|    let method = method.to_owned();
133|    let args = args.clone();
134|    let actor = actor.to_owned();
135|    tokio::spawn(async move {
136|        let _host = engine.lock_host_observation().await;
137|        let (record, replayed) = if method == "create_instance" {
138|            let input: incus::CreateInstanceInput = serde_json::from_value(args)?;
139|            let body = incus::native_creation_body(&input)?;
140|            let request = request(&input.operation_id, &actor, &session, &genesis,
141|                "incus", &input.operation_id, body)?;
142|            create_locked(&engine, request).await?
143|        } else {
144|            let input: incus::ReconcileNativeCreationInput = serde_json::from_value(args)?;
145|            let record = records(&engine).await?.into_iter()
146|                .find(|r| r.request.operation_id == input.operation_id)
147|                .context("native creation operation not found")?;
148|            ensure!(record.request.owner_kind == "incus" && record.request.actor_id == actor
149|                && record.request.caller_session == session && record.request.caller_genesis == genesis,
150|                "native creation operation belongs to another owner");
151|            (reconcile_locked(&engine, record).await?, true)
152|        };
153|        Ok(json!({"name":record.name,"operation_id":record.request.operation_id,
154|            "native_uuid":record.native_uuid,"phase":record.phase,"replayed":replayed,
155|            "created":true,"changes":[]}))
156|    }).await.context("native creation owner failed; reconcile the same operation")?
